"""Static protected conflict-review page; data comes only from the local RPC."""
import hashlib
from pathlib import Path

STYLE='''.columns.import-columns{grid-template-columns:repeat(2,minmax(0,1fr))}#import-section{background:#f8fbfd;border:1px solid #a8c5d3;border-radius:6px;padding:14px;margin:18px 0}#import-section>summary{font-size:18px;font-weight:700}.import-message{color:#96451a;font-weight:600;white-space:pre-wrap}@media(max-width:950px){.columns.import-columns{grid-template-columns:1fr}}.overview{margin:6px 0}.overview>div{padding:6px;border-bottom:1px solid #e6edf1}.overview>div.changed{background:#fff4d8;border-left:3px solid #c58913}.overview dt{font-size:12px;color:#506d7e}.overview dd{margin:0;overflow-wrap:anywhere;font-size:14px}.actions{position:sticky;bottom:0;padding:12px;background:#edf3f7;border-top:1px solid #b8cbd7;z-index:2}.message:not(:empty){position:sticky;top:0;background:#fff4d8;padding:10px;z-index:3}summary{cursor:pointer;color:#17657c}*{box-sizing:border-box}body{margin:0;background:#edf3f7;color:#17364b;font:15px/1.6 system-ui,sans-serif}header,main{max-width:1450px;margin:auto;padding:20px 28px}header{background:#123d56;color:white;max-width:none}header>div{max-width:1394px;margin:auto}h1{font-size:24px;margin:0}h2{font-size:18px}button{font:inherit;border:1px solid #8ba6b7;border-radius:5px;background:white;color:#143c55;padding:8px 15px;cursor:pointer}button.primary{background:#087b8b;color:white;border-color:#087b8b}button:disabled{opacity:.45;cursor:default}.toolbar{display:flex;gap:12px;align-items:center;flex-wrap:wrap;margin:14px 0}.hint{background:#e2eef5;padding:12px;border-left:4px solid #0c8d9c}.warning{background:#fff4d8;border-left:4px solid #d58d00;padding:12px}.message{min-height:28px;color:#a13418;font-weight:600}fieldset{border:1px solid #b8cbd7;border-radius:7px;margin:20px 0;padding:16px;background:white;min-width:0}legend{font-weight:700;padding:0 8px}.columns{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px}.side{border:2px solid #dbe6ed;border-radius:5px;padding:12px;min-width:0}.side.selected{border-color:#078799;background:#eefbfc}.side h3{margin:0 0 10px;font-size:15px}.side label{display:block;font-weight:700;cursor:pointer}.side pre{white-space:pre-wrap;overflow-wrap:anywhere;max-height:210px;overflow:auto;font:12px/1.5 Consolas,monospace}.missing{color:#a13418}input{accent-color:#087b8b}small{color:#506d7e}.detail{max-height:360px;overflow:auto;white-space:pre-wrap;overflow-wrap:anywhere;font:12px/1.5 Consolas,monospace}footer{margin:30px 0;color:#506d7e}.hidden{display:none!important}@media(max-width:950px){.columns{grid-template-columns:1fr}header,main{padding:14px}.side pre{max-height:130px}}'''
PAGE=('''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>驻马店 · 协同冲突处理</title><style>'''+STYLE+'''</style><header><div><h1>协同冲突处理</h1><div id="status">正在读取当前编辑会话…</div></div></header><main><details id="import-section" class="hidden"><summary>导入已有标绘到当前工程</summary><p>先预览，再确认合并。文件中缺少的图层或对象不会删除当前数据；同编号内容不同会逐项选择。请确认当前账号与目标工程。</p><div class="toolbar"><input id="import-file" type="file" accept=".json,application/json" aria-label="选择已保存标绘文件"><button id="import-preview" disabled>预览导入</button></div><p id="import-message" class="import-message" role="status" aria-live="polite"></p><p id="import-summary"></p><p id="import-name-warning" class="warning"></p><ul id="import-layers"></ul><div id="import-items"></div><div class="toolbar"><button id="import-previous" disabled>上一页</button><span id="import-page"></span><button id="import-next" disabled>下一页</button></div><div class="toolbar actions"><button id="import-apply" class="primary" disabled>确认合并到当前工程</button><span id="import-selected"></span></div><small>会先保存到本机同步工程，再交给同步端提交；云端是否接收以上方状态为准。源文件不会被覆盖，修改源文件后请重新选择。</small></details><p id="message" class="message" role="status" aria-live="polite"></p><section id="conflict-section"><p class="hint">① 比较共同基线与双方结果　② 为每项冲突选择保留哪一方　③ 提交选择。其他互不冲突的修改会继续保留；线和区域按完整对象选择，不拼接顶点。</p><div class="toolbar"><button id="refresh">重新读取比较</button><span id="progress"></span></div><div id="bulk" class="warning hidden"><strong>这份冲突需要按整份工程核对，当前无法安全逐项合并。</strong><p>选择某一方的整份工程会舍弃另一方未包含的修改。请先展开完整数据核对，再明确确认。</p><label><input type="checkbox" id="bulk-ack"> 我已核对，按整份工程采用所选一方</label></div><section id="items" aria-label="冲突比较"></section><div class="toolbar"><button id="previous">上一页</button><span id="page"></span><button id="next">下一页</button></div><div class="toolbar actions"><button id="apply" class="primary" disabled>提交选择并继续同步</button><span id="selected"></span></div><footer>提交成功会先保存到本机，随后由同步端核对云端版本。若工程在比较期间发生变化，请重新读取比较。关闭本窗口会保留尚未处理的冲突。</footer></section></main><script type="module" src="/review/app.mjs"></script></html>''').encode('utf-8')
CSP="default-src 'none'; script-src 'self'; style-src 'sha256-"+__import__('base64').b64encode(hashlib.sha256(STYLE.encode()).digest()).decode()+"'; connect-src 'self'; base-uri 'none'; frame-ancestors 'none'; form-action 'none'"

def asset(path):
    if path=='/review/':return PAGE,'text/html; charset=utf-8'
    if path=='/review/import.mjs':return (Path(__file__).resolve().parents[1]/'tools/layer_sync_import_review.mjs').read_bytes(),'text/javascript; charset=utf-8'
    if path=='/review/app.mjs':return (Path(__file__).resolve().parents[1]/'tools/layer_sync_conflict_review.mjs').read_bytes(),'text/javascript; charset=utf-8'
    raise ValueError('UNKNOWN_REVIEW_ASSET')